<script setup lang="ts">
import { onMounted,reactive,ref } from 'vue'
import { detalleDenuncia, detalleExpedientePad, listarDenuncias, listarExpedientesPad, registrarDenuncia } from '../services/pad'
import type { Denuncia, ExpedientePad, PadOptions } from '../interfaces/pad.interface'
const tab=ref<'denuncias'|'expedientes'>('denuncias'),denuncias=ref<Denuncia[]>([]),expedientes=ref<ExpedientePad[]>([]),options=ref<PadOptions>({tipos_denuncia:[],estados_denuncia:[],estados_pad:[]}),total=ref(0),lastPage=ref(1),loading=ref(false),saving=ref(false),error=ref(''),success=ref(''),modal=ref(false),detail=ref<Denuncia|ExpedientePad|null>(null),pdf=ref<File|null>(null)
const filters=reactive({criterio:'',estado:'',page:1}),form=reactive({tipo_denuncia:'',denunciante_id:'',denunciante_externo_id:'',fecha_hecho:'',fecha_toma_conocimiento:new Date().toISOString().slice(0,10),descripcion_hechos:'',investigados_personas:''})
async function load(page=1){filters.page=page;loading.value=true;error.value='';try{const r=tab.value==='denuncias'?await listarDenuncias(filters):await listarExpedientesPad(filters);total.value=r.total;lastPage.value=r.last_page;options.value=r.options;if(tab.value==='denuncias')denuncias.value=r.data as Denuncia[];else expedientes.value=r.data as ExpedientePad[]}catch(e){error.value=message(e)}finally{loading.value=false}}
function switchTab(value:'denuncias'|'expedientes'){tab.value=value;filters.estado='';load(1)}
function open(){Object.assign(form,{tipo_denuncia:'',denunciante_id:'',denunciante_externo_id:'',fecha_hecho:'',fecha_toma_conocimiento:new Date().toISOString().slice(0,10),descripcion_hechos:'',investigados_personas:''});pdf.value=null;modal.value=true}
async function save(){if(!form.tipo_denuncia||!form.fecha_toma_conocimiento||!form.descripcion_hechos.trim()){error.value='Complete el tipo, la fecha de conocimiento y la descripción de los hechos.';return}if(form.fecha_hecho&&form.fecha_toma_conocimiento<form.fecha_hecho){error.value='La fecha de conocimiento no puede ser anterior a la fecha del hecho.';return}const data=new FormData();Object.entries(form).forEach(([k,v])=>{if(k==='investigados_personas'){v.split(',').map(x=>x.trim()).filter(Boolean).forEach(id=>data.append('investigados_personas[]',id))}else if(v)data.append(k,v)});if(pdf.value)data.append('documento_pdf',pdf.value);saving.value=true;error.value='';try{await registrarDenuncia(data);modal.value=false;success.value='Denuncia registrada correctamente.';await load(1)}catch(e){error.value=message(e)}finally{saving.value=false}}
async function show(item:Denuncia|ExpedientePad){try{detail.value=tab.value==='denuncias'?await detalleDenuncia(item.id):await detalleExpedientePad(item.id)}catch(e){error.value=message(e)}}
function selectFile(e:Event){pdf.value=(e.target as HTMLInputElement).files?.[0]||null}function message(e:unknown){return e instanceof Error?e.message:'No se pudo completar la operación.'}onMounted(()=>load())
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / MAT / PAD</nav><header class="hero"><div class="mark">PAD</div><div><small>MAT · LEGAL</small><h1>Procedimiento Administrativo Disciplinario</h1><p>Control de denuncias, precalificación y expedientes disciplinarios.</p></div><strong>{{total}} registros</strong><button v-if="tab==='denuncias'" @click="open">+ Nueva denuncia</button></header><p v-if="success" class="flash">✓ {{success}}</p><p v-if="error" class="flash error">{{error}}</p>
<div class="tabs"><button :class="{active:tab==='denuncias'}" @click="switchTab('denuncias')">Denuncias</button><button :class="{active:tab==='expedientes'}" @click="switchTab('expedientes')">Expedientes PAD</button></div><section class="filters"><label>Buscar<input v-model.trim="filters.criterio" :placeholder="tab==='denuncias'?'Hechos, servidor o número':'Expediente, resolución, servidor o DNI'" @keyup.enter="load(1)"></label><label>Estado<select v-model="filters.estado"><option value="">Todos</option><option v-for="x in tab==='denuncias'?options.estados_denuncia:options.estados_pad" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><button @click="load(1)">Consultar</button></section><div v-if="loading" class="empty">Cargando información…</div>
<section v-else-if="tab==='denuncias'" class="cards"><article v-for="item in denuncias" :key="item.id"><header><b>Denuncia #{{item.id}}</b><em>{{item.estado_label||item.estado}}</em></header><dl><div><dt>Tipo</dt><dd>{{item.tipo_denuncia_label||item.tipo_denuncia}}</dd></div><div><dt>Fecha del hecho</dt><dd>{{item.fecha_hecho||'No indicada'}}</dd></div><div><dt>Investigados</dt><dd>{{item.investigados?.length||0}}</dd></div></dl><p>{{item.descripcion_hechos}}</p><div class="people"><span v-for="x in item.investigados" :key="x.id">{{x.nombre}}</span><small v-if="!item.investigados?.length">Aún no se identificaron investigados.</small></div><footer><span v-if="item.tiene_precalificacion">Precalificación: {{item.recomendacion}}</span><button @click="show(item)">Ver detalle</button></footer></article><div v-if="!denuncias.length" class="empty">No se encontraron denuncias.</div></section>
<section v-else class="table"><header><span>Expediente</span><span>Resolución de inicio</span><span>Investigados</span><span>Etapa</span><span>Vence descargo</span><span>Estado</span><span></span></header><article v-for="item in expedientes" :key="item.id"><b>{{item.numero_expediente}}</b><div><b>{{item.res_inicio_numero}}</b><small>{{item.res_inicio_fecha}}</small></div><span>{{item.investigados?.length||0}}</span><span>{{item.etapa||item.estado_label}}</span><time>{{item.fecha_vencimiento_descargos||'—'}}</time><em>{{item.estado_label||item.estado_pad}}</em><button @click="show(item)">Ver ficha</button></article><div v-if="!expedientes.length" class="empty">No se encontraron expedientes PAD.</div></section><footer v-if="lastPage>1" class="pages"><button :disabled="filters.page<=1" @click="load(filters.page-1)">Anterior</button><span>{{filters.page}} / {{lastPage}}</span><button :disabled="filters.page>=lastPage" @click="load(filters.page+1)">Siguiente</button></footer>
<div v-if="modal" class="backdrop" @mousedown.self="modal=false"><form class="modal" @submit.prevent="save"><header><div><small>NUEVO REGISTRO PAD</small><h2>Registrar denuncia</h2></div><button type="button" @click="modal=false">×</button></header><div class="grid"><label>Tipo de denuncia *<select v-model="form.tipo_denuncia"><option value="">Seleccione</option><option v-for="x in options.tipos_denuncia" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label>Fecha de conocimiento *<input v-model="form.fecha_toma_conocimiento" type="date"></label><label>Fecha del hecho<input v-model="form.fecha_hecho" type="date"></label><label>ID denunciante interno<input v-model.trim="form.denunciante_id" inputmode="numeric" placeholder="Opcional"></label><label>ID denunciante externo<input v-model.trim="form.denunciante_externo_id" inputmode="numeric" placeholder="Opcional"></label><label>IDs de investigados<input v-model.trim="form.investigados_personas" placeholder="Ej.: 15, 28, 41"><small>Separe múltiples identificadores con comas.</small></label></div><label>Descripción de los hechos *<textarea v-model.trim="form.descripcion_hechos" maxlength="2000" rows="5"></textarea></label><label>Documento sustentatorio PDF<input type="file" accept="application/pdf" @change="selectFile"><small>Opcional, máximo 20 MB.</small></label><footer><button type="button" class="clear" @click="modal=false">Cancelar</button><button :disabled="saving">{{saving?'Registrando…':'Registrar denuncia'}}</button></footer></form></div>
<div v-if="detail" class="backdrop" @mousedown.self="detail=null"><section class="modal detail"><header><div><small>{{tab==='denuncias'?'DETALLE DE DENUNCIA':'FICHA DEL EXPEDIENTE PAD'}}</small><h2>{{tab==='denuncias'?'Denuncia #'+detail.id:(detail as ExpedientePad).numero_expediente}}</h2></div><button @click="detail=null">×</button></header><template v-if="tab==='denuncias'"><div class="summary"><div><b>{{(detail as Denuncia).estado_label||(detail as Denuncia).estado}}</b><span>Estado</span></div><div><b>{{(detail as Denuncia).tipo_denuncia_label||(detail as Denuncia).tipo_denuncia}}</b><span>Tipo</span></div><div><b>{{(detail as Denuncia).fecha_toma_conocimiento}}</b><span>Conocimiento</span></div></div><p class="facts">{{(detail as Denuncia).descripcion_hechos}}</p></template><template v-else><div class="summary"><div><b>{{(detail as ExpedientePad).estado_label||(detail as ExpedientePad).estado_pad}}</b><span>Estado</span></div><div><b>{{(detail as ExpedientePad).res_inicio_numero}}</b><span>Resolución</span></div><div><b>{{(detail as ExpedientePad).fecha_vencimiento_descargos||'—'}}</b><span>Vence descargo</span></div></div></template><h3>Investigados y avance individual</h3><div class="list"><p v-if="!detail.investigados?.length">Sin investigados registrados.</p><div v-for="x in detail.investigados" :key="x.id"><b>{{x.nombre}} <i v-if="x.es_principal">Principal</i></b><span>{{x.dni||'Sin DNI'}} · {{x.cargo||'Cargo no indicado'}}</span><em>{{x.estado||'En investigación'}}</em></div></div><footer><button class="clear" @click="detail=null">Cerrar</button></footer></section></div></div></template>
<style scoped>
.page{--accent:#596a7b;color:#34444d}nav{margin-bottom:16px;color:#96a1a7;font-size:.7rem}nav a{color:var(--accent);text-decoration:none}.hero{padding:22px 25px;display:flex;align-items:center;gap:15px;border-left:5px solid var(--accent);border-radius:13px;background:#fff}.mark{width:52px;height:52px;display:grid;place-items:center;border-radius:11px;color:#fff;background:var(--accent);font-size:.58rem;font-weight:700}.hero small,.modal small{color:var(--accent);font-size:.55rem;font-weight:700}.hero h1{margin:2px 0;font-size:1.25rem}.hero p{margin:0;color:#7d898f;font-size:.65rem}.hero strong{margin-left:auto;font-size:.58rem}.hero button,.filters button,.pages button,.modal footer button{padding:8px 11px;border:0;border-radius:6px;color:#fff;background:var(--accent);font-size:.56rem}.flash{padding:10px;border-radius:8px;color:#286b50;background:#eff9f4;font-size:.63rem}.flash.error{color:#a13f43;background:#fff0f0}.tabs{margin-top:13px;display:flex;gap:4px}.tabs button{padding:10px 18px;border:0;border-radius:7px 7px 0 0;color:#718087;background:#e7ebed;font-size:.58rem;font-weight:700}.tabs button.active{color:#fff;background:var(--accent)}.filters{padding:12px;display:flex;align-items:end;gap:8px;border-radius:0 9px 9px 9px;background:#fff}.filters label{flex:1;font-size:.53rem}.filters label:first-child{flex:3}input,select,textarea{width:100%;padding:8px;border:1px solid #d8e0e4;border-radius:6px;font:inherit;font-size:.6rem}.cards{margin-top:13px;display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.cards article{display:flex;flex-direction:column;padding:14px;border-top:3px solid var(--accent);border-radius:9px;background:#fff}.cards article>header,.cards article>footer{display:flex;align-items:center;justify-content:space-between;gap:8px}.cards em,.table em,.list em{padding:4px 7px;border-radius:10px;color:#596a7b;background:#edf1f3;font-size:.49rem;font-style:normal}.cards dl{display:flex;gap:14px}.cards dt{color:#8a969c;font-size:.47rem}.cards dd{margin:2px 0;font-size:.55rem;font-weight:700}.cards article>p{min-height:34px;color:#66757c;font-size:.56rem}.people span{display:block;padding:3px 0;border-bottom:1px solid #eef1f2;font-size:.52rem}.cards footer{margin-top:auto;padding-top:10px}.cards footer span{color:#66757c;font-size:.49rem}.cards button,.table article>button{border:0;color:var(--accent);background:none;font-size:.52rem;font-weight:700}.table{margin-top:13px;border-radius:9px;background:#fff;overflow:hidden}.table>header,.table>article{padding:10px 12px;display:grid;grid-template-columns:1.2fr 1.2fr 75px 1fr 95px 95px 65px;align-items:center;gap:8px}.table>header{color:#fff;background:var(--accent);font-size:.5rem;font-weight:700}.table>article{border-bottom:1px solid #edf0f2;font-size:.54rem}.table small{display:block;color:#7d898f}.empty{grid-column:1/-1;margin-top:13px;padding:45px;text-align:center;background:#fff;font-size:.63rem}.pages{margin-top:12px;display:flex;justify-content:center;align-items:center;gap:8px;font-size:.55rem}.backdrop{position:fixed;z-index:100;inset:0;padding:20px;display:grid;place-items:center;background:#15283a88}.modal{width:min(100%,800px);max-height:92vh;overflow:auto;padding:20px;border-radius:12px;background:#fff}.modal>header{display:flex}.modal h2{margin:2px 0;font-size:1rem}.modal>header>button{margin-left:auto;border:0;background:none;font-size:1.4rem}.modal label{display:block;margin-bottom:10px;font-size:.56rem}.modal label small{display:block;margin-top:4px;color:#89959b}.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:8px}.modal footer{margin-top:14px;display:flex;justify-content:flex-end;gap:6px}.clear{color:#68757c!important;background:#edf1f3!important}.summary{margin:14px 0;display:grid;grid-template-columns:repeat(3,1fr);gap:7px}.summary div{padding:11px;text-align:center;border-radius:7px;background:#f0f3f5}.summary b,.summary span{display:block;font-size:.55rem}.facts{padding:12px;border-left:3px solid var(--accent);background:#f6f8f9;font-size:.6rem}.list div{padding:8px;display:grid;grid-template-columns:1.5fr 1fr auto;align-items:center;border-bottom:1px solid #e8ecee;font-size:.56rem}.list i{color:#37805f;font-size:.46rem}.detail{width:min(100%,900px)}@media(max-width:900px){.cards{grid-template-columns:1fr 1fr}.table>header{display:none}.table>article{grid-template-columns:1fr 1fr}.filters{align-items:stretch;flex-direction:column}.hero{flex-wrap:wrap}.hero strong{margin-left:0}}@media(max-width:560px){.cards,.grid,.summary,.table>article{grid-template-columns:1fr}}
</style>
